local CommonCardDisplayDialog = Class("CommonCardDisplayDialog")


function CommonCardDisplayDialog:__init()
    self.isPlaying   = false
    self.isShowAnim  = false
    self.isWaitNext  = false
    self.playCount   = 0
    self.playIndex   = 0
    self.cardInfos   = {}
    self.isAutoClose = false
    self.isHideShare = false
    self.isHideSkip  = false
    self.isSkin = false

    ---@type UnityEngine.Coroutine
    self.showDisplayCo = nil

    ---@type UnityEngine.Coroutine
    self.cardDisplayCo = nil

    ---@type fun():void
    self.clickCloseCb = nil

    ---@type fun():void
    self.clickSkipCb = nil

    ---@type fun():void
    self.animFinishCb = nil
end


function CommonCardDisplayDialog:__delete()
    self.isPlaying      = nil
    self.isShowAnim     = nil
    self.isWaitNext     = nil
    self.playCount      = nil
    self.playIndex      = nil
    self.cardInfos      = nil
    self.isAutoClose    = nil
    self.isHideShare    = nil
    self.isHideSkip     = nil
    self.showDisplayCo  = nil
    self.cardDisplayCo  = nil
    self.clickCloseCb   = nil
    self.clickSkipCb    = nil
    self.animFinishCb   = nil
    self.isSkin = nil
    self.skinBgTrans = nil
end


function CommonCardDisplayDialog:Awake()
    CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_card_get)
    CfUtils.SetAnimationAutomaticallyPlay(self.Root, false)
    self.skinBgTrans = self.BG.transform:Find("RoleSkinContainer/ImgRole")
    SetButtonAction(self.BtnSkip, Bind(self, self.OnClickBtnSkipAction))
    SetButtonAction(self.ClickBlankClose, Bind(self, self.OnClickBgAction))

    GameUtils.InstallShareButton(self.BtnShare, Constants.ShareType.CARD_RECEIVE, 'Prefabs/Share/GachaponResultShareShowDialog.prefab')
end


function CommonCardDisplayDialog:OnInitialize()
    return CoWaitDo(function()
        local initParams  = self.controller.Argument.parameters or {}
        self.cardInfos    = checkTable(initParams.cardInfo)
        self.playCount    = #self.cardInfos
        self.isAutoClose  = checkBool(initParams.autoClose)
        self.isHideSkip   = checkBool(initParams.isHideSkip)
        self.isHideShare  = true --- checkBool(initParams.isHideShare)
        self.clickSkipCb  = initParams.onSkipCb
        self.clickCloseCb = initParams.onCloseCb
        self.animFinishCb = initParams.finishCb
        self.isSkin = initParams.isSkin
        CfUtils.SetActive(self.BtnSkip, not self.isHideSkip)
        CfUtils.SetActive(self.BottomTips, false)
        --CfUtils.SetActive(self.RightPanel, not self.isHideShare)
    end)
end


function CommonCardDisplayDialog:OnFinalize()
    return CoWaitDo(function()
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        playerComponent:ClearRewardsDialogInfoByType(Constants.RewardDialogType.CardDisplay)

        Events.Broadcast(Constants.EventNames.CardDisplayDialogQuit)

        if self.showDisplayCo then
            CoStop(self.showDisplayCo)
            self.showDisplayCo = nil
        end
        if self.cardDisplayCo then
            CoStop(self.cardDisplayCo)
            self.cardDisplayCo = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
    end)
end


function CommonCardDisplayDialog:OnShow()
    return CoWaitDo(function()
        self:DoShowCards_()
    end)
end


function CommonCardDisplayDialog:Close()
    CfUtils.DialogBack()
end


