function CommonCardDisplayDialog:DoShowCards_()
    self.showDisplayCo = CoStart(function()

        -- init var
        self.isPlaying  = true
        self.isShowAnim = false
        self.isWaitNext = false

        -- play everyone
        for index = 1, self.playCount do
            self.playIndex = index

            self:ShowCardInfo_(index)
            while self.cardDisplayCo ~= nil do
                CoYield()
            end

            if self.isAutoClose then
            else
                while self.isWaitNext do
                    CoYield()
                end
            end
        end

        -- reset var
        self.isWaitNext = false
        self.isShowAnim = false
        self.isPlaying  = false

        -- finish
        if self.animFinishCb then
            self.animFinishCb()
        end
        if self.isAutoClose then
            self:Close()
        end

        self.showDisplayCo = nil
    end)
end


---@param showIndex integer
function CommonCardDisplayDialog:ShowCardInfo_(showIndex)
    self.cardDisplayCo = CoStart(function()
        local cardInfo = checkTable(self.cardInfos[showIndex])
        self:RefreshUI_(cardInfo.goodsId, cardInfo.isNew, cardInfo.level)
        local animationName = ShareRootAnimNameRoot
        if self.isSkin then
            animationName = ShareRootAnimNameRootSKinGo
        end
        local animTime  = CfUtils.GetAnimationTime(self.Root, animationName)
        self.isShowAnim = true
        CfUtils.SetActive(self.BottomTips, false)
        CfUtils.PlayAnimation(self.Root, animationName)
        CoYield(animTime)
        self.isShowAnim = false
        CfUtils.SetActive(self.BottomTips, not self.isAutoClose)

        self.cardDisplayCo = nil
        self.isWaitNext = showIndex < self.playCount
    end)
end


function CommonCardDisplayDialog:StopCarInfo_()
    if not isNull(self.cardDisplayCo) then
        CoStop(self.cardDisplayCo)
        self.cardDisplayCo = nil
    end
    if self.isShowAnim then
        CfUtils.StopAnimation(self.Root)
        self.isShowAnim = false
    end
    self.isWaitNext = self.playIndex < self.playCount
end


---@param cardId integer
---@param isNew boolean
---@param level integer
function CommonCardDisplayDialog:RefreshUI_(goodsId, isNew, level)
    CfUtils.SetActive(self.ImgNew, checkBool(isNew))
    local goodsType = GoodsUtils.GetIdType(goodsId)
    local cardId = goodsId
    local skinId = 0 
    if goodsType == Constants.IDType.CardSkin then
        ---@type CardSkinVo
        local skinVo = CfUtils.GetCfVo(AutoIds.IdSetting113 , "CardSkinVo" ,goodsId)
        cardId = skinVo.roleId
        skinId = goodsId
        local tag = skinVo.tag 
        local showTag = tag -1 > 0 and (tag -1) or 1 
        CfUtils.FillText(self.SkinName , skinVo.name)
        CfUtils.SetUISwitchImage(self.ImgSkinBg , showTag)
        if self.skinBgTrans then
            CfUtils.FillImage(self.skinBgTrans, skinVo.cardDrawing)
        end
        local text =localize("普通")
        ---@type CardProgressionConstants
        local CardProgressionConstants = import("Game.CardProgression.CardProgressionConstants")
        if tag == CardProgressionConstants.SkinTag.UR or tag == CardProgressionConstants.SkinTag.Rare then
            text = localize("稀有")
        elseif tag == CardProgressionConstants.SkinTag.Precious then
            text = localize("珍贵")
        elseif tag == CardProgressionConstants.SkinTag.Red then
            text = localize("传说")
        end
        CfUtils.FillText(self.SkinTagTxtName , text)
    end
    
    ---@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(cardId)
    local skinId = checkInt(skinId) > 0 and skinId or cardVo.defaultSkin
    -- 卡牌立绘
    ---@type CardSkinVo
    local skinVo = cardConfMgr:GetCardSkinBySkinId(skinId)
    self.RoleImage:Execute(skinVo.skinId)
    self.RoleShadow:Execute(skinVo.skinId)
    self.RoleEffect:Execute(skinVo.skinId)

    ---@type CardComponent
    local cardComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardDojo = cardComp:GetCardByConfId(cardId)

    -- 卡牌品质
    local cardRare = (isNew and cardDojo) and cardDojo:GetRare() or checkInt(cardVo.rare)
    CfUtils.SetUISwitchText(self.TxtCat, cardRare)
    CfUtils.SetUISwitchText(self.CardName, cardRare)
    CfUtils.SetUISwitchImage(self.ImgRareIcon, cardRare)
    CfUtils.SetUISwitchImage(self.ImgRareIcon2, cardRare)
    CfUtils.SetUISwitchImage(self.ImgRareIconbg, cardRare)
    CfUtils.SetUISwitchImage(self.ImgFloorLine, cardRare)
    CfUtils.SetUISwitchParticleSystem(self.RareParticle1, cardRare)
    CfUtils.SetUISwitchParticleSystem(self.RareParticle2, cardRare)
    CfUtils.SetUISwitchParticleSystem(self.RareParticle3, cardRare)

    -- 卡牌名称/角色名
    ---@type RolesVo
    local roleVo = cardConfMgr:GetRolesVo(cardVo.characterId) or {}
    CfUtils.FillText(self.RoleEngName, tostring(roleVo.englishName))
    CfUtils.FillText(self.RoleName, tostring(roleVo.name))

    local cardLevel = checkInt(level)
    local cardName  = tostring(cardVo.name)
    if cardLevel > 1 then
        CfUtils.FillText(self.CardName, localize('Lv._num_ _roleName_·_cardName_', {_num_ = cardLevel, _roleName_ = tostring(roleVo.name), _cardName_ = cardName}))
    else
        CfUtils.FillText(self.CardName, localize('_roleName_·_cardName_', {_num_ = cardLevel, _roleName_ = tostring(roleVo.name), _cardName_ = cardName}))
    end
    
    -- 卡牌属性
    local cardAttr = checkInt(cardVo.attributeType)
    CfUtils.SetUISwitchImage(self.ElementImg, cardAttr)
    CfUtils.FillText(self.ElementTxt, cardConfMgr:GetRoleAttributeColorVo(cardAttr).name)

    -- 卡牌职业
    local cardCareer = checkInt(cardVo.career)
    CfUtils.SetUISwitchImage(self.CareerImg, cardCareer)
    CfUtils.FillText(self.CareerTxt, cardConfMgr:GetCardCareerRowByType(cardCareer).name)

    -- 卡牌阵营
    local cardRace = checkInt(cardVo.race)
    CfUtils.FillImage(self.RaceTypeImg, CardUtils.GetCardRaceIconPath(cardRace))
    CfUtils.FillText(self.RaceTypeTxt, cardConfMgr:GetRoleRaceVoById(cardRace).name)

    -- 角色声优
    CfUtils.FillText(self.TxtCVName, localize('CV: _name_', {_name_ = cardVo.cv}))

    -- 播放当前卡牌的台词
    ---@type RoleVoiceVo
    local roleVoiceVo = roleVoiceMgr:PlayDrawCardVoiceByCardId(cardId, nil, skinId)
    if roleVoiceVo then
        CfUtils.FillText(self.TxtCVContent, roleVoiceVo:GetDesk())
    else
        local errorTips = string.format("卡牌<%s>未在【角色表/角色台词表】找到对应数据", tostring(cardId))
        if Config.DEBUG then
            CfUtils.FillText(self.TxtCVContent, string.format("<color=#FF66FF>%s</color>", errorTips))
        else
            printError(errorTips)
        end
    end
end

