function CommonCardDisplayDialog:OnClickBgAction()
    if self.isShowAnim then return end  -- is playing, to wait

    if self.isWaitNext then
        self.isWaitNext = false  -- to next

    elseif self.isPlaying then
        self:StopCarInfo_()

    else
        if self.clickCloseCb then
            self.clickCloseCb()
        else
            self:Close()
        end
    end
end


function CommonCardDisplayDialog:OnClickBtnSkipAction()
    if self.clickSkipCb then
        self.clickSkipCb()
    else
        self:Close()
    end
end

---------------------------------------------------
--- click handler end --
---------------------------------------------------

return CommonCardDisplayDialog